import countriesJson from '../data/countries.json'

// Facts about one country, generated by scripts/make-country-data.mjs.
export type CountryFacts = {
  // ISO 3166-1 alpha-3 code, e.g. "PER". Links facts to the globe outlines.
  isoAlpha3: string
  commonName: string
  officialName: string
  // Most countries have one capital; a few have several (e.g. South Africa).
  capitals: string[]
  // Total area including inland water, in square kilometres.
  areaKm2: number
  population: number
  populationYear: number
  // Inequality-adjusted Human Development Index (0–1). Null when UNDP has no
  // value for the country, shown as "no data".
  ihdi: number | null
  ihdiYear: number | null
}

// All 195 countries (193 UN members + Vatican City and Palestine), keyed by
// ISO alpha-3 code.
export const countryFacts: Record<string, CountryFacts> = countriesJson
